            item={k:value(q.get(k),limit,k) for k,limit in [('text',1500),('explanation',3000)]};kind=q['type'];item['type']=kind
            if norm(item['text']) in prompts:raise InvalidInput('Повторений текст питання.')
            prompts.add(norm(item['text']));item['fact_date']=check_date(q.get('fact_date'));item['verified_at']=check_date(q.get('verified_at'));item['historical']=q.get('historical',True)
            if item['verified_at']<item['fact_date'] or type(item['historical'])!=bool:raise InvalidInput('Некоректна дата.')
            ss=q.get('sources')
