            item['sources']=[]
            for src in ss:
                if not isinstance(src,dict):raise InvalidInput('Некоректне джерело.')
                url=value(src.get('url'),2000,'url');u=urlparse(url)
                if u.scheme not in ('https','http') or not u.netloc or u.username or u.password or any(ord(x)<32 for x in url):raise InvalidInput('Некоректне посилання.')
                item['sources'].append({'url':url,'title':value(src.get('title'),250,'джерело')})
            concepts=q.get('concepts')
            if not isinstance(concepts,list) or not 1<=len(concepts)<=12:raise InvalidInput('Потрібні ідентифікатори фактів concepts.')
            item['concepts']=[value(x,200,'concept') for x in concepts]
            if len(set(item['concepts']))!=len(item['concepts']):raise InvalidInput('Дубльований concept.')
            if kind=='text':
                keys=q.get('accepted_answers')
                if not isinstance(keys,list) or not 1<=len(keys)<=20:raise InvalidInput('Потрібен текстовий ключ.')
                item['accepted_answers']=[value(x,100,'ключ') for x in keys]
                if len({norm(x) for x in item['accepted_answers']})!=len(keys):raise InvalidInput('Дубльований ключ.')
            elif kind in ('single','multiple'):
                opts=q.get('options')
                if not isinstance(opts,list) or not 2<=len(opts)<=12:raise InvalidInput('Потрібно 2–12 варіантів.')
                item['options']=[];ids=set();labels=set()
                for o in opts:
                    if not isinstance(o,dict):raise InvalidInput('Некоректний варіант.')
                    oid=value(o.get('id'),40,'id');label=value(o.get('text'),300,'варіант');ok=o.get('is_correct')
                    if type(ok)!=bool or oid in ids or norm(label) in labels:raise InvalidInput('Повторений або некоректний варіант.')
